// Rate plot and rate plane on a setting page (plan.md Phase 3b d). Hand-rolled SVG, no library.
// Data: <script id="plot-data"> written by site/build.py from data/canonical/site_index.json.
// Each bound carries js = {args, body}: a JavaScript expression generated by pipeline/site_index.py
// (our own pipeline, not user input) for the bound on the uniform-gap instance.
document.addEventListener("DOMContentLoaded", function () {
  var host = document.getElementById("rateplot");
  var raw = document.getElementById("plot-data");
  if (!host || !raw) return;
  var data = JSON.parse(raw.textContent);
  var NS = "http://www.w3.org/2000/svg";
  // T starts at 10: bounds with log T factors are 0 at T = 1 and would dive to -infinity on log axes
  var RANGE = { T: [10, 1e9], K: [2, 1e4], d: [2, 1e4], Delta: [1e-3, 0.5], delta: [1e-6, 0.5], epsilon: [1e-3, 1] };
  var NAME = { T: "T", K: "K", d: "d", Delta: "Δ", delta: "δ", epsilon: "ε" };
  var INT = { T: 1, K: 1, d: 1 };
  var vals = {};
  data.sliders.forEach(function (v) { vals[v] = data.defaults[v] != null ? data.defaults[v] : 1; });

  var css = function (n) { return getComputedStyle(document.documentElement).getPropertyValue(n).trim(); };
  var el = function (tag, attrs, parent) {
    var x = document.createElementNS(NS, tag);
    for (var k in attrs) x.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(x);
    return x;
  };
  var h = function (tag, cls, parent, text) {
    var x = document.createElement(tag);
    if (cls) x.className = cls;
    if (text != null) x.textContent = text;
    if (parent) parent.appendChild(x);
    return x;
  };
  var sup = function (n) {
    var m = { "-": "⁻", "0": "⁰", "1": "¹", "2": "²", "3": "³", "4": "⁴", "5": "⁵", "6": "⁶", "7": "⁷", "8": "⁸", "9": "⁹" };
    return String(n).split("").map(function (c) { return m[c] || c; }).join("");
  };
  var fmt = function (v) {
    if (!isFinite(v)) return "–";
    var a = Math.abs(v);
    if (a >= 1e5 || (a > 0 && a < 1e-3)) {
      var e = Math.floor(Math.log10(a)), m = v / Math.pow(10, e);
      return (Math.abs(m - 1) < 0.005 ? "" : m.toFixed(2) + "·") + "10" + sup(e);
    }
    return Number(v.toPrecision(3)).toLocaleString("en");
  };
  var tex = function (node, s) {
    if (window.katex && s) {
      try { katex.render(s, node, { throwOnError: false, strict: "ignore" }); return; } catch (err) { /* fall through */ }
    }
    node.textContent = s || "";
  };

  // compile once
  data.bounds.forEach(function (b) {
    b.fn = null;
    if (!b.js) return;
    try { b.fn = new Function(b.js.args.join(","), "return " + b.js.body); } catch (err) { b.fn = null; b.err = String(err); }
  });
  var evalAt = function (b, v) {
    if (!b.fn) return NaN;
    var a = b.js.args.map(function (k) {
      if (k === "delta" && b.dsub) return 1 / v.T;
      return v[k];
    });
    try { return b.fn.apply(null, a); } catch (err) { return NaN; }
  };

  // ------------------------------------------------------------ layout
  var regimes = data.regimes;
  var state = { reg: regimes[0].key, x: "T", off: {}, frontsOnly: false, hover: null, planeY: null };
  try {
    var saved = JSON.parse(sessionStorage.getItem("bb-plot") || "{}");
    if (saved.x) state.x = saved.x;
  } catch (err) { /* ignore */ }

  host.innerHTML = "";
  var controls = h("div", "rp-controls", host);
  var regWrap = h("label", "fsel", controls);
  h("span", "", regWrap, "Regime");
  var regSel = h("select", "", regWrap);
  regimes.forEach(function (r) {
    var o = h("option", "", regSel, r.label + (r.statusLabel ? " — " + r.statusLabel : ""));
    o.value = r.key;
  });
  var xWrap = h("div", "seg", controls);
  h("span", "", xWrap, "x");
  var sliderBox = h("div", "rp-sliders", host);
  var grid = h("div", "rp-grid", host);
  var chartBox = h("div", "rp-chart", grid);
  var legend = h("div", "rp-legend", grid);
  var note = h("p", "rp-note small muted", host);
  var planeHead = h("div", "rp-controls rp-plane-head", host);
  h("h3", "", planeHead, "Rate plane");
  var planeYWrap = h("div", "seg", planeHead);
  var planeBox = h("div", "rp-plane", host);
  var planeNote = h("p", "rp-note small muted", host);
  var tip = h("div", "rp-tip", document.body);
  tip.hidden = true;

  var inRegime = function () { return data.bounds.filter(function (b) { return b.reg === state.reg; }); };
  var varsOf = function (bs) {
    var s = {};
    bs.forEach(function (b) { if (b.fn) b.js.args.forEach(function (a) { s[a] = 1; }); });
    if (s.delta && bs.some(function (b) { return b.dsub; })) s.T = 1;
    return data.sliders.filter(function (v) { return s[v]; });
  };
  var colour = function (b) { return b.side === "lower" ? css("--s2") : css("--s1"); };
  var visible = function (b) { return !state.off[b.id] && (!state.frontsOnly || b.front); };
  var label = function (b) { return (b.shape ? "∝ " : "") + b.cite + (b.alg ? " · " + b.alg : ""); };

  // ------------------------------------------------------------ controls
  var buildControls = function () {
    var bs = inRegime();
    var vs = varsOf(bs);
    if (vs.indexOf(state.x) === -1) state.x = vs.indexOf("T") !== -1 ? "T" : (vs[0] || "T");
    while (xWrap.children.length > 1) xWrap.removeChild(xWrap.lastChild);
    vs.forEach(function (v) {
      var b = h("button", "", xWrap, NAME[v]);
      b.type = "button";
      b.setAttribute("aria-pressed", String(v === state.x));
      b.addEventListener("click", function () {
        state.x = v;
        try { sessionStorage.setItem("bb-plot", JSON.stringify({ x: v })); } catch (err) { /* ignore */ }
        buildControls(); draw();
      });
    });
    sliderBox.innerHTML = "";
    vs.filter(function (v) { return v !== state.x; }).forEach(function (v) {
      var r = RANGE[v] || [1e-3, 1e3];
      var lab = h("label", "rp-slider", sliderBox);
      h("span", "rp-sname", lab, NAME[v] + " =");
      var inp = h("input", "", lab);
      inp.type = "range"; inp.min = Math.log10(r[0]); inp.max = Math.log10(r[1]); inp.step = 0.01;
      inp.value = Math.log10(vals[v]);
      inp.setAttribute("aria-label", NAME[v]);
      var out = h("output", "", lab, fmt(vals[v]));
      if (v === "delta" && bs.some(function (b) { return b.dsub; })) {
        h("span", "muted small", lab, "(δ = 1/T for w.h.p. bounds read in expectation)");
      }
      inp.addEventListener("input", function () {
        var x = Math.pow(10, Number(inp.value));
        if (INT[v]) x = Math.max(r[0], Math.round(x));
        vals[v] = x;
        out.textContent = fmt(x);
        draw();
      });
    });
    if (!sliderBox.children.length) h("span", "muted small", sliderBox, "No other variables in this regime.");
    buildLegend();
  };

  var buildLegend = function () {
    legend.innerHTML = "";
    var bs = inRegime();
    var bar = h("div", "rp-lbar", legend);
    [["all", function () { state.off = {}; state.frontsOnly = false; }],
     ["best only", function () { state.off = {}; state.frontsOnly = true; }],
     ["none", function () { bs.forEach(function (b) { state.off[b.id] = true; }); state.frontsOnly = false; }]]
      .forEach(function (t) {
        var b = h("button", "", bar, t[0]);
        b.type = "button";
        b.addEventListener("click", function () { t[1](); buildLegend(); draw(); });
      });
    ["upper", "lower"].forEach(function (side) {
      var items = bs.filter(function (b) { return b.side === side; });
      if (!items.length) return;
      items.sort(function (a, b) { return (b.front - a.front) || (a.inh - b.inh) || (a.shape - b.shape) || ((a.year || 0) - (b.year || 0)); });
      h("div", "rp-lhead", legend, (side === "upper" ? "Upper bounds" : "Lower bounds") + " (" + items.length + ")");
      var ul = h("ul", "", legend);
      items.forEach(function (b) {
        var li = h("li", (b.fn ? "" : "noplot") + (b.front ? " front" : ""), ul);
        var lab = h("label", "", li);
        var cb = h("input", "", lab);
        cb.type = "checkbox";
        cb.checked = visible(b);
        cb.disabled = !b.fn;
        cb.addEventListener("change", function () {
          state.off[b.id] = !cb.checked;
          if (cb.checked && state.frontsOnly && !b.front) state.frontsOnly = false;
          draw();
        });
        var sw = h("span", "rp-key" + (side === "lower" ? " lo" : "") + (b.shape ? " shape" : ""), lab);
        sw.style.borderTopColor = colour(b);
        var txt = h("span", "rp-ltxt", lab);
        h("b", "", txt, (b.shape ? "∝ " : "") + b.cite);
        if (b.alg) h("span", "muted", txt, " · " + b.alg);
        var tags = [];
        if (b.front) tags.push("best");
        if (b.inh) tags.push("inherited");
        if (b.dsub) tags.push("δ = 1/T");
        if (b.restricted) tags.push("restricted");
        if (!b.fn) tags.push("not plottable");
        if (tags.length) h("span", "rp-tags", txt, tags.join(" · "));
        var f = h("span", "rp-ltex", li);
        if (b.tex) tex(f, b.tex); else f.textContent = b.expr || "";
        li.addEventListener("mouseenter", function () { state.hover = b.id; draw(true); });
        li.addEventListener("mouseleave", function () { state.hover = null; draw(true); });
      });
    });
  };

  regSel.addEventListener("change", function () { state.reg = regSel.value; state.off = {}; state.frontsOnly = false; buildControls(); draw(); });

  // ------------------------------------------------------------ rate plot
  var NPTS = 140;
  var cache = null;
  var compute = function () {
    var bs = inRegime().filter(function (b) { return b.fn && visible(b); });
    var r = RANGE[state.x] || [1, 1e6];
    var l0 = Math.log10(r[0]), l1 = Math.log10(r[1]);
    var xs = [];
    for (var i = 0; i < NPTS; i++) xs.push(Math.pow(10, l0 + (l1 - l0) * i / (NPTS - 1)));
    var series = bs.map(function (b) {
      var ys = xs.map(function (x) {
        var v = Object.assign({}, vals);
        v[state.x] = x;
        var y = evalAt(b, v);
        return (isFinite(y) && y > 0) ? y : null;
      });
      return { b: b, ys: ys };
    });
    return { xs: xs, series: series, l0: l0, l1: l1 };
  };

  var draw = function (hoverOnly) {
    if (!hoverOnly || !cache) cache = compute();
    var c = cache;
    var W = Math.max(280, chartBox.clientWidth || 600), H = Math.min(400, Math.max(260, W * 0.6));
    var m = { l: 56, r: 12, t: 12, b: 38 };
    chartBox.innerHTML = "";
    var svg = el("svg", { width: W, height: H, viewBox: "0 0 " + W + " " + H, role: "img",
                          "aria-label": "Bounds against " + NAME[state.x] + ", log-log" }, chartBox);
    var all = [];
    c.series.forEach(function (s) { s.ys.forEach(function (y) { if (y != null) all.push(y); }); });
    var empty = !all.length;
    all.sort(function (a, b) { return a - b; });
    // robust y-range: ignore the most extreme 1% so one wild bound doesn't flatten the rest
    var lo = empty ? 1 : all[Math.floor(all.length * 0.01)], hi = empty ? 10 : all[Math.min(all.length - 1, Math.ceil(all.length * 0.99))];
    var y0 = Math.floor(Math.log10(lo)), y1 = Math.ceil(Math.log10(hi));
    if (y1 - y0 < 1) { y0 -= 1; y1 += 1; }
    var px = function (x) { return m.l + (Math.log10(x) - c.l0) / (c.l1 - c.l0) * (W - m.l - m.r); };
    var py = function (y) { return H - m.b - (Math.log10(y) - y0) / (y1 - y0) * (H - m.t - m.b); };
    var grid = el("g", { class: "rp-gridlines" }, svg);
    var ystep = Math.max(1, Math.ceil((y1 - y0) / 8));
    for (var k = y0; k <= y1; k += ystep) {
      el("line", { x1: m.l, x2: W - m.r, y1: py(Math.pow(10, k)), y2: py(Math.pow(10, k)) }, grid);
      var t = el("text", { x: m.l - 6, y: py(Math.pow(10, k)) + 4, "text-anchor": "end", class: "rp-tick" }, svg);
      t.textContent = "10" + sup(k);
    }
    var xstep = Math.max(1, Math.ceil((c.l1 - c.l0) / 8));
    for (var j = Math.ceil(c.l0); j <= Math.floor(c.l1); j += xstep) {
      el("line", { x1: px(Math.pow(10, j)), x2: px(Math.pow(10, j)), y1: m.t, y2: H - m.b }, grid);
      var tx = el("text", { x: px(Math.pow(10, j)), y: H - m.b + 16, "text-anchor": "middle", class: "rp-tick" }, svg);
      tx.textContent = "10" + sup(j);
    }
    el("line", { x1: m.l, x2: W - m.r, y1: H - m.b, y2: H - m.b, class: "rp-axis" }, svg);
    var xl = el("text", { x: (m.l + W - m.r) / 2, y: H - 4, "text-anchor": "middle", class: "rp-alabel" }, svg);
    xl.textContent = NAME[state.x] + " (log scale)";
    var yl = el("text", { x: 12, y: (m.t + H - m.b) / 2, "text-anchor": "middle", class: "rp-alabel",
                          transform: "rotate(-90 12 " + (m.t + H - m.b) / 2 + ")" }, svg);
    yl.textContent = "bound (log scale)";
    var clipId = "rpclip";
    var defs = el("defs", {}, svg);
    var cp = el("clipPath", { id: clipId }, defs);
    el("rect", { x: m.l, y: m.t, width: W - m.l - m.r, height: H - m.t - m.b }, cp);
    var plot = el("g", { "clip-path": "url(#" + clipId + ")" }, svg);
    // trivial bound T (regret-type quantities): reference only
    var fam = state.reg.split("|")[0];
    if (/regret/.test(fam) && fam !== "simple_regret" && (state.x === "T" || vals.T)) {
      var d0 = "";
      c.xs.forEach(function (x, i) {
        var T = state.x === "T" ? x : vals.T;
        d0 += (i ? "L" : "M") + px(x).toFixed(1) + "," + py(T).toFixed(1);
      });
      el("path", { d: d0, class: "rp-trivial" }, plot);
      var tl = el("text", { x: W - m.r - 4, y: Math.max(m.t + 12, Math.min(H - m.b - 4, py(state.x === "T" ? c.xs[c.xs.length - 1] : vals.T) + 14)),
                            "text-anchor": "end", class: "rp-tlabel" }, svg);
      tl.textContent = "trivial: T";
    }
    // series: non-best first, best on top, hovered last
    var order = c.series.slice().sort(function (a, b) {
      return (a.b.id === state.hover) - (b.b.id === state.hover) || a.b.front - b.b.front;
    });
    order.forEach(function (s) {
      var d = "", pen = false;
      s.ys.forEach(function (y, i) {
        if (y == null) { pen = false; return; }
        d += (pen ? "L" : "M") + px(c.xs[i]).toFixed(1) + "," + py(y).toFixed(1);
        pen = true;
      });
      if (!d) return;
      var b = s.b;
      var cls = "rp-line" + (b.side === "lower" ? " lo" : "") + (b.shape ? " shape" : "") + (b.front ? " front" : "") +
                (state.hover ? (b.id === state.hover ? " hl" : " dim") : "");
      el("path", { d: d, class: cls, stroke: colour(b) }, plot);
    });
    if (empty) {
      var et = el("text", { x: (m.l + W - m.r) / 2, y: (m.t + H - m.b) / 2, "text-anchor": "middle", class: "rp-alabel" }, svg);
      et.textContent = "Nothing to plot for these values";
    }
    // crosshair + tooltip
    var cross = el("line", { y1: m.t, y2: H - m.b, class: "rp-cross", visibility: "hidden" }, svg);
    var dots = el("g", {}, svg);
    var overlay = el("rect", { x: m.l, y: m.t, width: W - m.l - m.r, height: H - m.t - m.b, fill: "transparent" }, svg);
    var move = function (ev) {
      var box = svg.getBoundingClientRect();
      var mx = ev.clientX - box.left;
      var i = Math.round((mx - m.l) / (W - m.l - m.r) * (NPTS - 1));
      i = Math.max(0, Math.min(NPTS - 1, i));
      var X = px(c.xs[i]);
      cross.setAttribute("x1", X); cross.setAttribute("x2", X); cross.setAttribute("visibility", "visible");
      dots.innerHTML = "";
      var rows = c.series.filter(function (s) { return s.ys[i] != null; })
        .sort(function (a, b) { return b.ys[i] - a.ys[i]; });
      rows.forEach(function (s) {
        var Y = py(s.ys[i]);
        if (Y < m.t || Y > H - m.b) return;
        el("circle", { cx: X, cy: Y, r: s.b.id === state.hover ? 4.5 : 3, fill: colour(s.b), class: "rp-dot" }, dots);
      });
      tip.innerHTML = "";
      h("div", "rp-thead", tip, NAME[state.x] + " = " + fmt(c.xs[i]));
      var shown = rows;
      if (state.hover) shown = rows.filter(function (s) { return s.b.id === state.hover; }).concat(rows.filter(function (s) { return s.b.id !== state.hover; }));
      shown.slice(0, 12).forEach(function (s) {
        var r = h("div", "rp-trow" + (s.b.id === state.hover ? " hl" : ""), tip);
        var k = h("span", "rp-key" + (s.b.side === "lower" ? " lo" : "") + (s.b.shape ? " shape" : ""), r);
        k.style.borderTopColor = colour(s.b);
        h("b", "", r, fmt(s.ys[i]));
        h("span", "", r, " " + label(s.b) + (s.b.front ? " ★" : ""));
      });
      if (rows.length > 12) h("div", "muted", tip, "+" + (rows.length - 12) + " more");
      if (!rows.length) h("div", "muted", tip, "no finite positive values here");
      tip.hidden = false;
      var tx = ev.clientX + 16, ty = ev.clientY + 14;
      if (tx + tip.offsetWidth > window.innerWidth - 8) tx = ev.clientX - tip.offsetWidth - 16;
      if (ty + tip.offsetHeight > window.innerHeight - 8) ty = Math.max(8, window.innerHeight - tip.offsetHeight - 8);
      tip.style.left = Math.max(4, tx) + "px";
      tip.style.top = ty + "px";
    };
    overlay.addEventListener("pointermove", move);
    overlay.addEventListener("pointerdown", move);
    overlay.addEventListener("pointerleave", function () { tip.hidden = true; cross.setAttribute("visibility", "hidden"); dots.innerHTML = ""; });

    // note: counts
    var bs = inRegime();
    var nplot = bs.filter(function (b) { return b.fn; }).length;
    var bad = c.series.filter(function (s) { return s.ys.every(function (y) { return y == null; }); }).length;
    var nshape = bs.filter(function (b) { return b.shape; }).length;
    var parts = [];
    parts.push("Upper bounds solid (blue), lower bounds dashed (orange); ★ / thicker = best bound in this regime (the comparison front).");
    parts.push("\u201cTight\u201d means equal growth rate up to constant factors: lower bounds often have small constants (e.g. 1/20, 1/504), so a parallel dashed line well below the solid ones is tight, not a gap.");
    if (nshape) parts.push("∝ fainter lines are O/Θ/Ω bounds drawn with constant 1: their shape, not their level.");
    parts.push("Instance-dependent sums use a uniform-gap instance (all gaps Δ).");
    if (bs.length - nplot) parts.push((bs.length - nplot) + " of " + bs.length + " bounds have no plottable form.");
    if (bad) parts.push(bad + " shown bound" + (bad > 1 ? "s are" : " is") + " non-positive or undefined over the whole range (check the extraction).");
    note.textContent = parts.join(" ");
    if (!hoverOnly) drawPlane();
  };

  // ------------------------------------------------------------ rate plane
  var parseRate = function (s) {
    if (s == null) return null;
    var p = String(s).split("·log^");
    return [Number(p[0]), p.length > 1 ? Number(p[1]) : 0];
  };
  var drawPlane = function () {
    var reg = regimes.filter(function (r) { return r.key === state.reg; })[0];
    var bs = inRegime().filter(function (b) { return b.prof && !b.dsub; });
    var ys = {};
    bs.forEach(function (b) { ["K", "d", "Delta"].forEach(function (v) { if (b.prof[v]) ys[v] = 1; }); });
    var yopts = ["K", "d", "Delta"].filter(function (v) { return ys[v]; });
    if (state.planeY == null || yopts.indexOf(state.planeY) === -1) state.planeY = yopts[0] || null;
    while (planeYWrap.firstChild) planeYWrap.removeChild(planeYWrap.firstChild);
    if (yopts.length) {
      h("span", "", planeYWrap, "y");
      yopts.forEach(function (v) {
        var b = h("button", "", planeYWrap, v === "Delta" ? "1/Δ" : NAME[v]);
        b.type = "button";
        b.setAttribute("aria-pressed", String(v === state.planeY));
        b.addEventListener("click", function () { state.planeY = v; drawPlane(); });
      });
    }
    planeBox.innerHTML = "";
    if (!bs.length) {
      planeNote.textContent = "No bound in this regime has a growth profile.";
      return;
    }
    var Y = state.planeY;
    var key = function (b, v) { var p = b.prof[v] || [0, 0]; return p; };
    var groups = {};
    bs.forEach(function (b) {
      var px_ = key(b, "T"), py_ = Y ? key(b, Y) : [0, 0];
      var k = b.side + "|" + px_.join(",") + "|" + py_.join(",");
      (groups[k] = groups[k] || { side: b.side, x: px_, y: py_, items: [], front: false }).items.push(b);
      if (b.front) groups[k].front = true;
    });
    var gl = Object.keys(groups).map(function (k) { return groups[k]; });
    // best fronts from the comparison (per-variable rates), when both sides exist
    var pv = (reg && reg.perVar) || {};
    var fu = null, fl = null;
    if (pv.T || (Y && pv[Y])) {
      var gx = function (side) { var r = pv.T ? parseRate(pv.T[side]) : [0, 0]; return r; };
      var gy = function (side) { var r = Y && pv[Y] ? parseRate(pv[Y][side]) : [0, 0]; return r; };
      fu = { x: gx("upper"), y: gy("upper") }; fl = { x: gx("lower"), y: gy("lower") };
    }
    var W = Math.max(280, planeBox.clientWidth || 600), H = Math.min(340, Math.max(240, W * 0.5));
    var m = { l: 48, r: 16, t: 14, b: 38 };
    var LOGW = 0.07;  // horizontal/vertical offset per extra log factor
    var xv = function (r) { return r[0] + LOGW * r[1]; };
    var xsV = gl.map(function (g) { return xv(g.x); }), ysV = gl.map(function (g) { return xv(g.y); });
    var xmin = Math.min(0, Math.min.apply(null, xsV)), xmax = Math.max(1, Math.max.apply(null, xsV) + 0.15);
    var ymin = Math.min(0, Math.min.apply(null, ysV)), ymax = Math.max(1, Math.max.apply(null, ysV) + 0.15);
    var sx = function (v) { return m.l + (v - xmin) / (xmax - xmin) * (W - m.l - m.r); };
    var sy = function (v) { return H - m.b - (v - ymin) / (ymax - ymin) * (H - m.t - m.b); };
    var svg = el("svg", { width: W, height: H, viewBox: "0 0 " + W + " " + H, role: "img",
                          "aria-label": "Rate plane: T exponent against " + (Y || "") + " exponent" }, planeBox);
    var g0 = el("g", { class: "rp-gridlines" }, svg);
    for (var a = Math.ceil(xmin * 2) / 2; a <= xmax; a += 0.5) {
      el("line", { x1: sx(a), x2: sx(a), y1: m.t, y2: H - m.b }, g0);
      el("text", { x: sx(a), y: H - m.b + 15, "text-anchor": "middle", class: "rp-tick" }, svg).textContent = String(a);
    }
    for (var bb = Math.ceil(ymin * 2) / 2; bb <= ymax; bb += 0.5) {
      el("line", { x1: m.l, x2: W - m.r, y1: sy(bb), y2: sy(bb) }, g0);
      el("text", { x: m.l - 6, y: sy(bb) + 4, "text-anchor": "end", class: "rp-tick" }, svg).textContent = String(bb);
    }
    el("text", { x: (m.l + W - m.r) / 2, y: H - 4, "text-anchor": "middle", class: "rp-alabel" }, svg).textContent = "exponent of T";
    var ylab = Y ? "exponent of " + (Y === "Delta" ? "1/Δ" : Y) : "";
    el("text", { x: 12, y: (m.t + H - m.b) / 2, "text-anchor": "middle", class: "rp-alabel",
                 transform: "rotate(-90 12 " + (m.t + H - m.b) / 2 + ")" }, svg).textContent = ylab;
    if (fu && fl) {
      el("line", { x1: sx(xv(fu.x)), y1: sy(xv(fu.y)), x2: sx(xv(fl.x)), y2: sy(xv(fl.y)), class: "rp-gapline" }, svg);
    }
    gl.sort(function (a, b) { return a.front - b.front; });
    gl.forEach(function (g) {
      var cx = sx(xv(g.x)), cy = sy(xv(g.y));
      var r = 5 + 2 * Math.sqrt(g.items.length - 1);
      var col = g.side === "lower" ? css("--s2") : css("--s1");
      if (g.front) el("circle", { cx: cx, cy: cy, r: r + 3.5, class: "rp-ring", stroke: col }, svg);
      el("circle", { cx: cx, cy: cy, r: r, fill: col, class: "rp-pt" + (g.side === "lower" ? " lo" : "") + (g.front ? " front" : "") }, svg);
      var hit = el("circle", { cx: cx, cy: cy, r: Math.max(12, r + 4), fill: "transparent" }, svg);
      var show = function (ev) {
        tip.innerHTML = "";
        var rt = function (p, v) { return (p[0] ? v + (p[0] === 1 ? "" : "^" + p[0]) : "") + (p[1] ? (p[0] ? "·" : "") + "log" + (p[1] === 1 ? "" : "^" + p[1]) : "") || "1"; };
        h("div", "rp-thead", tip, (g.side === "upper" ? "Upper" : "Lower") + ": " + rt(g.x, "T") + (Y ? " · " + rt(g.y, Y === "Delta" ? "(1/Δ)" : Y) : "") +
          (g.front ? "  ★ best" : ""));
        g.items.slice(0, 10).forEach(function (b) { h("div", "rp-trow", tip, label(b) + (b.inh ? " (inherited)" : "")); });
        if (g.items.length > 10) h("div", "muted", tip, "+" + (g.items.length - 10) + " more");
        tip.hidden = false;
        var tx = ev.clientX + 16;
        if (tx + tip.offsetWidth > window.innerWidth - 8) tx = ev.clientX - tip.offsetWidth - 16;
        tip.style.left = Math.max(4, tx) + "px"; tip.style.top = (ev.clientY + 14) + "px";
      };
      hit.addEventListener("pointermove", show);
      hit.addEventListener("pointerdown", show);
      hit.addEventListener("pointerleave", function () { tip.hidden = true; });
    });
    var txt = "Each bound as a point (exponent of T, exponent of " + (Y === "Delta" ? "1/Δ" : (Y || "–")) +
      "); size = number of bounds with that rate; ringed = best (front). Small offsets mark extra log factors (+" + LOGW + " per log).";
    if (fu && fl) txt += " The grey segment joins the best upper and best lower rates: its length is the gap.";
    planeNote.textContent = txt;
  };

  regSel.value = state.reg;
  buildControls();
  draw();
  var rt = null;
  window.addEventListener("resize", function () { clearTimeout(rt); rt = setTimeout(function () { draw(); }, 150); });
  if (window.matchMedia) {
    var mq = window.matchMedia("(prefers-color-scheme: dark)");
    if (mq.addEventListener) mq.addEventListener("change", function () { buildLegend(); draw(); });
  }
  window.addEventListener("load", function () { buildLegend(); draw(); });
});
